// Option 1: Mark as intentionally failing (recommended for demo purposes)
test.fail('broken selector always fails — dedup demo @regression', async ({ page }) => {
  await page.goto('/');
  await expect(page.locator('#this-element-does-not-exist')).toBeVisible({ timeout: 3000 });
});

// Option 2: Assert the element is NOT visible (invert the assertion)
test('element is not present — dedup demo @regression', async ({ page }) => {
  await page.goto('/');
  await expect(page.locator('#this-element-does-not-exist')).not.toBeVisible({ timeout: 3000 });
});

// Option 3: Replace with a real locator
test('real element is visible — dedup demo @regression', async ({ page }) => {
  await page.goto('/');
  await expect(page.locator('#actual-element-id')).toBeVisible({ timeout: 3000 });
});
